# region: render
def render(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: fold
def fold(xs):
    return [v for v in xs if v % 2 == 0]

# region: digest
def digest(xs, factor=10):
    return [v * factor for v in xs]

# region: sift
def sift(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (min(xs) - min(xs)) if xs else 0}

# region: emit
def emit(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return emit(sift(digest(fold(render(raw)))))

